import request from 'supertest';
import { createApp } from 'C:/Users/Enzof/OneDrive/Documentos/Semana Tech/semana-academica/api/src/app.js';

const app: any = createApp({ modoTeste: true });

async function main() {
  await request(app).post('/_teste/reset');

  const criacao = await request(app)
    .post('/atividades')
    .set('X-Usuario', 'org-ana')
    .send({
      titulo: 'Minicurso para emissão',
      tipo: 'minicurso',
      salaId: 'lab-3',
      vagas: 10,
      encontros: [19, 20, 21, 22].map((dia) => ({
        inicio: `2026-10-${dia}T19:00:00-03:00`,
        fim: `2026-10-${dia}T22:00:00-03:00`
      }))
    });
  const atividadeId = criacao.body.id;
  const encontros = criacao.body.encontros;

  await request(app).post(`/atividades/${atividadeId}/inscricoes`).set('X-Usuario', 'p-carla');

  for (const enc of encontros) {
    const dia = enc.inicio.slice(8, 10);
    await request(app).put('/_teste/relogio').send({ agora: `2026-10-${dia}T19:30:00-03:00` });
    const codigoRes = await request(app)
      .get(`/encontros/${enc.id}/codigo`)
      .set('X-Usuario', 'org-ana');
    await request(app)
      .post(`/encontros/${enc.id}/presencas`)
      .set('X-Usuario', 'p-carla')
      .send({ codigo: codigoRes.body.codigo });
  }

  await request(app).put('/_teste/relogio').send({ agora: '2026-10-24T10:00:00-03:00' });

  const emitido = await request(app)
    .post(`/atividades/${atividadeId}/certificado`)
    .set('X-Usuario', 'p-carla');
  console.log('EMISSAO:', emitido.status, JSON.stringify(emitido.body));

  const semHeader = await request(app).get(`/certificados/${emitido.body.codigo}`);
  const comHeader = await request(app)
    .get(`/certificados/${emitido.body.codigo}`)
    .set('X-Usuario', 'p-carla');
  const inexistente = await request(app).get('/certificados/SA26-AAAA-BBBB');

  console.log('GET sem X-Usuario:', semHeader.status, JSON.stringify(semHeader.body));
  console.log('GET com X-Usuario:', comHeader.status, JSON.stringify(comHeader.body));
  console.log('GET inexistente:', inexistente.status, JSON.stringify(inexistente.body));

  app?.close?.();
}

main();

